import json,html
from pathlib import Path
D=Path('artifacts/facts-images');inspect=json.loads((D/'language-inspection.json').read_text(encoding='utf-8'));first=json.loads((D/'pilot-status.json').read_text(encoding='utf-8'));later=json.loads((D/'completed-language-pilots.json').read_text(encoding='utf-8'));titles={x['region_code']:x['title'] for x in first+later};names={'ko':'韩文','id':'印尼语','th':'泰文','ar':'阿拉伯文','ja':'日文','zh-HK':'繁体中文','vi':'越南语','pt':'葡萄牙语','es':'西班牙语','en':'英文（SA / MY / AF）'};order=['ko','id','zh-HK','en','th','ar','ja','vi','pt','es'];inspect.sort(key=lambda x:order.index(x['language']));e=lambda v:html.escape(str(v));cards=[]
for x in inspect:
 r=x['region'];src='facts-images/pilot/'+x.get('image_file',r+'.jpg');cards.append('<article><header><h2>'+e(names[x['language']])+'</h2><b class="'+('pass' if x['supported'] else 'fail')+'">'+('通过' if x['supported'] else '不通过：输出英文')+'</b></header><a href="'+src+'" target="_blank"><img src="'+src+'" alt="'+e(names[x['language']])+'测试图"></a><p><strong>稿件：</strong>'+e(titles[r])+'</p><p><strong>图上主文字：</strong>'+e(x['text'])+'</p></article>')
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WikiFX 头图语言测试</title><style>body{margin:0;background:#f1f4f8;color:#172338;font:15px/1.6 system-ui,sans-serif}main{max-width:1440px;margin:auto;padding:24px}h1{margin:0}h2{font-size:20px;margin:0}header{display:flex;justify-content:space-between;gap:16px;padding:16px}section{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}article{background:white;border:1px solid #d6dfea;border-radius:12px;overflow:hidden}img{width:100%;display:block;aspect-ratio:800/450}p{padding:0 16px;overflow-wrap:anywhere}.pass{color:#087444}.fail{color:#ae2635}@media(max-width:700px){section{grid-template-columns:1fr}main{padding:12px}}</style><main><h1>头图语言测试 · 2026-10-27</h1><p>逐张检查主文案语言；点击图片查看原尺寸。4 种语言通过、6 种语言暂不支持。失败测试图已从审稿头图和送稿附件中排除。</p><section>'''+''.join(cards)+'</section></main></html>'
Path('artifacts/image-language-tests.html').write_text(page,encoding='utf-8');print(len(cards),'test images exported')
